package common

import("bytes";"encoding/json";"fmt";"net/http";"strings")
type MastodonAdapter struct{ BaseURL,Token string; Client *http.Client }
func(a MastodonAdapter) ParseEvent(payload map[string]any)(InboundEvent,error){status:=payload;if nested,ok:=payload["status"].(map[string]any);ok{status=nested};account,_:=status["account"].(map[string]any);user,_:=account["id"].(string);if user==""{user,_=status["user_id"].(string)};if user==""{return InboundEvent{},fmt.Errorf("Mastodon status has no account")};event:=InboundEvent{Platform:"mastodon",UserID:user,ContentType:"text"};event.Text,_=status["content"].(string);if id,ok:=status["id"].(string);ok{event.ReplyToID=id};if media,ok:=status["media_attachments"].([]any);ok&&len(media)>0{item,_:=media[0].(map[string]any);event.MediaURL,_=item["url"].(string);event.ContentType=fmt.Sprint(item["type"]);if event.ContentType==""{event.ContentType="file"}};return event,nil}
func(a MastodonAdapter)SendReply(event InboundEvent,reply OutboundReply)error{client:=a.Client;if client==nil{client=http.DefaultClient};for _,message:=range reply.Messages{if message.Type!="text"{return fmt.Errorf("Mastodon media upload is required before media replies")};data,_:=json.Marshal(map[string]any{"status":message.Text,"in_reply_to_id":event.ReplyToID});req,_:=http.NewRequest(http.MethodPost,strings.TrimRight(a.BaseURL,"/")+"/api/v1/statuses",bytes.NewReader(data));req.Header.Set("Authorization","Bearer "+a.Token);req.Header.Set("Content-Type","application/json");resp,err:=client.Do(req);if err!=nil{return err};resp.Body.Close();if resp.StatusCode/100!=2{return fmt.Errorf("Mastodon API returned %s",resp.Status)}};return nil}
